        L.push("");
        L.push("tier " + b.tier + " \xB7 ~" + fmtW(b.compressedTokens) + " tokens" + (b.createdAt ? " \xB7 " + fmtDT(b.createdAt) : "") + (rr ? " \xB7 " + rr : "") + (b.external ? " \xB7 \u26A1" + t("det.block_external") : ""));
