        L.push("- session id: " + d.id);
        L.push("- blocks: " + d.blockDetails.length + " (" + d.blockDetails.filter((x) => x.active).length + " active)");
        d.blockDetails.forEach((b) => { L.push(""); L.push(buildBlockMd(b)); });
        return L.join("\\n");
